"use client";

import { motion } from "framer-motion";

// One set of positions (in vw / vh) per section, in the same order as SECTIONS
const POSITIONS = [
  [{ x: -10, y: -15 }, { x: 55, y: 45 }, { x: 15, y: 60 }],
  [{ x: 40, y: -10 }, { x: -15, y: 40 }, { x: 60, y: 65 }],
  [{ x: 10, y: 30 }, { x: 60, y: -10 }, { x: 35, y: 70 }],
  [{ x: 55, y: 15 }, { x: 0, y: 60 }, { x: 30, y: -15 }],
  [{ x: 20, y: -5 }, { x: 65, y: 55 }, { x: -10, y: 50 }],
  [{ x: 50, y: 40 }, { x: 5, y: -10 }, { x: 40, y: 70 }],
];

const COLORS = ["var(--primary)", "var(--primary-2)", "var(--secondary)"];

export default function AnimatedBackground({ activeIndex }: { activeIndex: number }) {
  const positions = POSITIONS[activeIndex] ?? POSITIONS[0];

  return (
    <div aria-hidden className="pointer-events-none fixed inset-0 -z-10 overflow-hidden">
      {positions.map((p, i) => (
        <motion.div
          key={i}
          className="absolute top-0 left-0 size-[45vmax] rounded-full opacity-20 blur-3xl"
          style={{ background: COLORS[i] }}
          animate={{ x: `${p.x}vw`, y: `${p.y}vh` }}
          transition={{ duration: 1.6, ease: "easeInOut" }}
        />
      ))}

      {/* Faint grid */}
      <div
        className="absolute inset-0 opacity-60"
        style={{
          backgroundImage:
            "linear-gradient(var(--card-border) 1px, transparent 1px), linear-gradient(90deg, var(--card-border) 1px, transparent 1px)",
          backgroundSize: "56px 56px",
          maskImage: "radial-gradient(ellipse at center, black 25%, transparent 75%)",
          WebkitMaskImage: "radial-gradient(ellipse at center, black 25%, transparent 75%)",
        }}
      />
    </div>
  );
}